-- Komponentmallar: färdiga uppsättningar komponenter (t.ex. ett luftbehandlingsaggregat) som läggs till i ett projekt.
-- Gemensamma för alla projekt. "xx" i beteckningar ersätts med ett nummer när mallen används.
CREATE TABLE IF NOT EXISTS komponentmall (
    "Id" uuid NOT NULL PRIMARY KEY,
    "Namn" text NOT NULL UNIQUE,
    "Rader" text NOT NULL,
    "Andrad" timestamp with time zone NOT NULL DEFAULT now(),
    "AndradAv" text NOT NULL DEFAULT ''
);

-- Kontrollmallar: listor med kontrollpunkter. Typ = projekt (Projektspecifika kontroller),
-- projektering (Projekteringsegenkontroll) eller service (Kontroller under Service).
CREATE TABLE IF NOT EXISTS kontrollmall (
    "Id" uuid NOT NULL PRIMARY KEY,
    "Typ" text NOT NULL,
    "Namn" text NOT NULL,
    "Beskrivning" text NOT NULL DEFAULT '',
    "Punkter" text NOT NULL DEFAULT '[]',
    "Andrad" timestamp with time zone NOT NULL DEFAULT now(),
    "AndradAv" text NOT NULL DEFAULT '',
    UNIQUE ("Typ", "Namn")
);

-- Kontroller i ett projekt. Raderna (kontrollpunkterna) ligger i listrad med Lista = 'kontroll-<Id>'.
CREATE TABLE IF NOT EXISTS kontroll (
    "Id" uuid NOT NULL PRIMARY KEY,
    "ProjektId" uuid NOT NULL REFERENCES projekt ("Id") ON DELETE CASCADE,
    "Typ" text NOT NULL,
    "Namn" text NOT NULL,
    "Beskrivning" text NOT NULL DEFAULT '',
    "MallNamn" text NOT NULL DEFAULT '',
    "Ordning" integer NOT NULL DEFAULT 0,
    "Andrad" timestamp with time zone NOT NULL DEFAULT now(),
    "AndradAv" text NOT NULL DEFAULT ''
);
CREATE INDEX IF NOT EXISTS "IX_kontroll_ProjektId_Typ" ON kontroll ("ProjektId", "Typ");

