INSERT INTO kontrollmall ("Id", "Typ", "Namn", "Beskrivning", "Punkter", "AndradAv") VALUES ('77f889b8-451b-4aad-aa1d-01d9465499f9', 'service', 'Servicebesök Beckhoff', 'Servicebesök - Beckhoff - Panel-PC - SCADA/HMI - APPARATSKÅP', '["Utför en okulär utvändig kontroll av apparatskåp", "Finns driftkort, flödesbilder samt apparatskåpsritning. Är det den senaste versionen/relationshandling?", "Utför en okulär invändig kontroll av apparatskåp", "Är PLCn i drift (Lyser TC-lampa grönt)?", "Går det att ansluta mot PLC med dokumenterade inloggningsuppgifter anv/lös?", "Går det att gå \"online\" med det senaste utcheckade programmet?", "Utför en okulär kontroll av samtliga system ute i anläggningen, kontrollera rum, teknikutrymmen, inuti luftbehandlingsaggregat samt kabelförläggning.", "Kontrollera värden från anläggningen, är temperaturer, tryck, flöden mm. rimliga och stämmer det mot verkligheten?", "Kontrollera inställningar, larmgränser, tidkanaler, så att det är inom rimliga gränser.", "Kontrollera Panel-PC och att alla inställningar stämmer", "Kontrollera bilder i HMI/SCADA okulärt", "Dokumentera inställningar på kurvor, börvärden, larmgränser, gränsvärden för start/stop", "Kontrollera insvängningsförlopp för reglerande komponenter, tryckgivare, temperaturgivare, flödesgivare mm.", "Kontrollera aktiva/inaktiva larm. Hämta hem larmanalys och dokumentera onormal larmaktivitet.", "Ta backup av anläggningen PLC/Web Port", "Utför kontroll av återuppstart efter spänningsbortfall om möjligt."]', 'Dagens program') ON CONFLICT DO NOTHING;
